@import "@fontsource-variable/inter";

/* Light (faithful): a white page, pale blue-grey cards (235,240,248), near-black ink
   (34,35,38) with body copy at 60%, black pill buttons, and soft tints at the foot of cards:
   peach, green, blue, pink, teal; lavender as the glow; iOS-orange stars as the highlight. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.256 0.006 271);
  --card: oklch(0.954 0.012 260);
  --card-foreground: oklch(0.256 0.006 271);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.256 0.006 271);
  --primary: oklch(0.256 0.006 271);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.97 0.004 271);
  --secondary-foreground: oklch(0.256 0.006 271);
  --muted: oklch(0.93 0.014 262);
  --muted-foreground: oklch(0.256 0.006 271 / 60%);
  --accent: oklch(0.916 0.041 256);
  --accent-foreground: oklch(0.256 0.006 271);
  --destructive: oklch(0.691 0.177 38);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.256 0.006 271 / 10%);
  --input: oklch(0.842 0.004 271);
  --ring: oklch(0.55 0.218 269);
  --highlight: oklch(0.765 0.175 63);
  --highlight-foreground: oklch(0.256 0.006 271);
  --glow: oklch(0.775 0.126 293);
  --chart-1: oklch(0.818 0.105 36);
  --chart-2: oklch(0.743 0.244 141);
  --chart-3: oklch(0.55 0.218 269);
  --chart-4: oklch(0.835 0.083 343);
  --chart-5: oklch(0.855 0.092 191);
  --sidebar: oklch(0.97 0.004 271);
  --sidebar-foreground: oklch(0.256 0.006 271);
  --sidebar-primary: oklch(0.256 0.006 271);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.954 0.012 260);
  --sidebar-accent-foreground: oklch(0.256 0.006 271);
  --sidebar-border: oklch(0.256 0.006 271 / 10%);
  --sidebar-ring: oklch(0.55 0.218 269);

  --typeface-body: "Inter Variable", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --typeface-display: "Inter Variable", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1rem;
  --page-width: 90rem;
  --page-gutter: 1rem;
  --section-y: 5rem;
}

/* Dark: the site's charcoal band (31,32,37) as a whole page, with slightly lifted charcoal
   cards, white ink at 60% for body copy, white pill buttons and the same tints, a touch
   brighter. */
.dark {
  --background: oklch(0.245 0.01 277);
  --foreground: oklch(1 0 0);
  --card: oklch(0.3 0.01 277);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.3 0.01 277);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(1 0 0);
  --primary-foreground: oklch(0.245 0.01 277);
  --secondary: oklch(0.33 0.01 277);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.33 0.012 277);
  --muted-foreground: oklch(1 0 0 / 60%);
  --accent: oklch(0.36 0.03 270);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.72 0.17 38);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 18%);
  --ring: oklch(0.65 0.17 269);
  --highlight: oklch(0.79 0.17 63);
  --highlight-foreground: oklch(0.245 0.01 277);
  --glow: oklch(0.72 0.14 293);
  --chart-1: oklch(0.75 0.12 36);
  --chart-2: oklch(0.6 0.12 165);
  --chart-3: oklch(0.62 0.19 269);
  --chart-4: oklch(0.75 0.11 343);
  --chart-5: oklch(0.78 0.1 191);
  --sidebar: oklch(0.21 0.01 277);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(1 0 0);
  --sidebar-primary-foreground: oklch(0.245 0.01 277);
  --sidebar-accent: oklch(0.3 0.01 277);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 12%);
  --sidebar-ring: oklch(0.65 0.17 269);
}
